suppressPackageStartupMessages(library(DESeq2))
o<-'results/bulk/curated';stopifnot(file.exists(file.path(o,'COMPLETE')))
r<-read.csv(file.path(o,'differential_expression.csv'));a<-read.csv(file.path(o,'gene_annotation.csv'));q<-read.csv(file.path(o,'library_qc.csv'))
x<-read.table(gzfile('data/raw/GSE247373_countsAll.txt.gz'),header=TRUE,check.names=FALSE)
m<-read.delim('config/bulk_samples.tsv');d<-readRDS(file.path(o,'deseq2.rds'))
stopifnot(nrow(a)==nrow(x),!anyDuplicated(a$gene_id),nrow(q)==12,all(q$total_gene_counts==colSums(x[,-1])),ncol(d)==9,identical(as.integer(table(d$condition)),c(4L,5L)))
y<-as.matrix(x[match(rownames(d),x[[1]]),match(colnames(d),names(x)),drop=FALSE]);stopifnot(all(y==counts(d)),all(rowSums(y>=10)>=3),identical(r$gene_id,rownames(d)))
z<-as.data.frame(results(d,contrast=c('condition','liver_72h','liver_24h'),alpha=.05))
stopifnot(isTRUE(all.equal(r$log2FoldChange,z$log2FoldChange)),isTRUE(all.equal(r$padj,z$padj)))
l<-read.csv(file.path(o,'leave_one_out.csv'));stopifnot(nrow(l)==9*nrow(r),length(unique(l$omitted))==9)
lm<-matrix(l$log2FoldChange,nrow=nrow(r));stopifnot(all(r$loo_same_direction==(rowSums(sign(lm)==sign(r$log2FoldChange),na.rm=TRUE)==9)))
h<-read.csv(file.path(o,'hallmark.csv'))
for(v in unique(h$variant)){z<-h[h$variant==v,];stopifnot(isTRUE(all.equal(z$padj,p.adjust(z$pval,'BH'))))}
rank<-read.csv(file.path(o,'rank_feature_selection.csv'));stopifnot(!anyDuplicated(rank$symbol),all(rank$symbol_count==1))
cat('Bulk validation passed: raw count conservation, sample units, contrast, annotations, nine omission fits, pathway BH.\n')
